"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9070],{3006:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldGuiController","desc":"Drives every copy of the train shield readout \u2014 the diegetic `TrainShieldGui`\\nSurfaceGui cloned onto each tagged `TrainShieldMonitor` part, and the\\nfull-screen `TrainShieldGui` ScreenGui in `PlayerGui` that the monitor\'s\\nsecond ProximityPrompt zooms into. Both assets share one element layout under\\n`MainContainer.SafeContainer`, so one resolver and one render path serve both.\\n\\nTwo readouts are live today: the shield fraction (eased, banded\\nHEALTHY/WARNING/DANGER per `TrainConfig.ShieldBands`) and shield capacity\\n(`TrainStateCache.ShieldMax()` over `TrainConfig.BASE_SHIELD`, which already\\ncarries Tech Tree and perk buffs). The other three \u2014 strength rating,\\nefficiency, auto-regeneration \u2014 read `ReplicatedStorage.ResearchBuffs`\\nattributes and fall back to stock values until the Tech Tree writes them.\\n\\nThe zoom panel is modal: opening it reveals the cursor (via\\n`Signals.RequestMouseIcon`, so `CameraController` stays the sole owner of\\n`MouseBehavior`) and hides the rest of the HUD \u2014 Roblox\'s topbar, Satchel\'s\\nhotbar, and the TopbarPlus icons, each needing its own switch.\\n\\nThis controller holds no fallback snapshot of its own; while the cache has\\nnone, the shield readouts show a placeholder instead of a guess. Stats update\\non shield sync and buff change rather than per frame \u2014 only the eased shield\\nnumber needs `RenderStepped`. Each monitor owns a Janitor that destroys its\\nclone when the tag is removed.","realm":["Client"],"source":{"line":31,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldGuiController.client.luau"}}')}}]);